solutions.naive:
class Solution:
    def bulbSwitch(self, n: int) -> int:
        root = 0
        while (root + 1) * (root + 1) <= n:
            root += 1
        return root

solutions.better:
class Solution:
    def bulbSwitch(self, n: int) -> int:
        if n == 0:
            return 0
        x = n
        while True:
            y = (x + n // x) // 2
            if y >= x:
                return x
            x = y

solutions.optimal:
class Solution:
    def bulbSwitch(self, n: int) -> int:
        lo, hi, ans = 0, n, 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if mid * mid <= n:
                ans = mid
                lo = mid + 1
            else:
                hi = mid - 1
        return ans

